const initialState = {
  firstName: localStorage.getItem('firstName') || '',
  lastName: localStorage.getItem('lastName') || '',
  email: localStorage.getItem('email') || '',
  password: localStorage.getItem('password') || '',
  confirmPassword: localStorage.getItem('confirmPassword') || '',
  dob: localStorage.getItem('dob') || '',
  gender: localStorage.getItem('gender') || '',
  confirm: JSON.parse(localStorage.getItem('confirm')) || false,
};

function formReducer(state = initialState, action) {
  switch (action.type) {
    case 'UPDATE_FIELD':
      localStorage.setItem(
        action.field,
        action.field === 'confirm' ? JSON.stringify(action.value) : action.value
      );
      return { ...state, [action.field]: action.value };
    case 'RESET_FORM':
      Object.keys(state).forEach((key) => localStorage.removeItem(key));
      return { ...initialState };
    default:
      return state;
  }
}

export default formReducer;
